void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 1024;
    int phase_rand = rand() % 100;
    if ((phase_rand -= 50) < 0) {
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if ((phase_rand -= 30) < 0) {
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if ((phase_rand -= 15) < 0) {
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    } else {
        for (int i = 1; i <= vars; i++) saved[i] = value[i];
    }
}
